   double grake_norm = 0.0;
   if (W_total > 0.0) {
     for (int k = 0; k < st.K; k++) {
       const int nj = st.cat_counts[k];
       for (int j = 0; j < nj; j++) {
         const auto& cells = cells_by_margin_cat[cat_offset[k] + j];
         double S_kj = 0.0;
